#!/usr/bin/env node
/**
 * release-notes-writer.js — bilingual weekly release notes across all repos.
 *
 * For each WizeLife repo:
 *   - run `git log --since='7 days ago' --no-merges --pretty=format:%H|%cI|%s`
 *   - group commits by Conventional-Commit prefix (feat/fix/qa/chore/...)
 *   - skip merge commits & obviously auto-generated ones
 *
 * Writes /tmp/release-notes-{YYYY-MM-DD}.md with Hebrew + English sections
 * per app.  Tables are in English even within the Hebrew section (RTL breaks
 * alignment), per project convention.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const REPOS = [
  { dir: "/Users/s/Desktop/Desktop - O’s MacBook Air/TOTALIST/wizelife", name: 'WizeLife (portal)', he: 'WizeLife (פורטל)' },
  { dir: "/Users/s/Desktop/Desktop - O’s MacBook Air/tax master", name: 'WizeTax (Tax Master)', he: 'WizeTax (Tax Master)' },
  { dir: "/Users/s/Desktop/Desktop - O’s MacBook Air/finance dashboard", name: 'WizeMoney (FinSight)', he: 'WizeMoney (FinSight)' },
  { dir: "/Users/s/Desktop/Desktop - O’s MacBook Air/RAMBAM", name: 'WizeHealth (Vitara / RAMBAM)', he: 'WizeHealth (Vitara / RAMBAM)' },
  { dir: "/Users/s/Desktop/Desktop - O’s MacBook Air/wizetravel-app", name: 'WizeTravel (app)', he: 'WizeTravel (אפליקציה)' },
  { dir: "/Users/s/Desktop/Desktop - O’s MacBook Air/Check Deal", name: 'WizeDeal (Check Deal)', he: 'WizeDeal (Check Deal)' },
  { dir: "/Users/s/Desktop/Desktop - O’s MacBook Air/mega traveller", name: 'Mega Traveller', he: 'Mega Traveller' },
];

const SINCE = '7 days ago';

// Conventional-Commit groupings.
// Order here = order in the report.
const GROUPS = [
  { key: 'feat',     en: 'Features',         he: 'תכונות' },
  { key: 'fix',      en: 'Bug fixes',        he: 'תיקוני באגים' },
  { key: 'perf',     en: 'Performance',      he: 'ביצועים' },
  { key: 'security', en: 'Security',         he: 'אבטחה' },
  { key: 'qa',       en: 'QA / tests',       he: 'QA / טסטים' },
  { key: 'test',     en: 'QA / tests',       he: 'QA / טסטים' },     // merged with qa
  { key: 'refactor', en: 'Refactoring',      he: 'ריפקטור' },
  { key: 'docs',     en: 'Docs',             he: 'תיעוד' },
  { key: 'i18n',     en: 'i18n',             he: 'תרגום (i18n)' },
  { key: 'style',    en: 'Style / UI',       he: 'עיצוב / UI' },
  { key: 'ui',       en: 'Style / UI',       he: 'עיצוב / UI' },    // merged with style
  { key: 'chore',    en: 'Chores',           he: 'תחזוקה' },
  { key: 'build',    en: 'Build',            he: 'בנייה (build)' },
  { key: 'ci',       en: 'CI',               he: 'CI' },
  { key: 'revert',   en: 'Reverts',          he: 'ביטולים' },
  { key: 'other',    en: 'Other',            he: 'אחר' },
];
// Map "test" → "qa" and "ui" → "style" so they merge.
const GROUP_ALIASES = { test: 'qa', ui: 'style' };

/* ─────────────────────────── helpers ──────────────────────────────────── */

function isGitRepo(dir) {
  try { fs.statSync(path.join(dir, '.git')); return true; }
  catch { return false; }
}

function gitLog(dir) {
  // Use --no-merges; format with NUL/pipe separators to avoid quoting issues.
  try {
    const out = execSync(
      `git -C "${dir}" log --since="${SINCE}" --no-merges --pretty=format:%H%x09%cI%x09%an%x09%s`,
      { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 },
    );
    return out.split('\n').filter(Boolean).map((line) => {
      const [hash, iso, author, subject] = line.split('\t');
      return { hash: hash || '', iso: iso || '', author: author || '', subject: subject || '' };
    });
  } catch (e) {
    return [];
  }
}

function isAutoGenerated(c) {
  const s = (c.subject || '').toLowerCase();
  if (!s) return true;
  // common bot / auto-generated patterns
  if (/^merge\b/.test(s)) return true;
  if (/^revert "merge\b/.test(s)) return true;
  if (/dependabot|renovate|github-actions/.test(c.author.toLowerCase())) return true;
  if (/\bauto[- ]?generated\b/.test(s)) return true;
  if (/^bump (sw|cache|version)/.test(s) && s.length < 25) return true; // tiny version bumps
  return false;
}

// Extract conventional prefix → group key
const PREFIX_RE = /^([a-zA-Z]+)(?:\([^)]+\))?!?\s*:\s*(.*)$/;
function classify(subject) {
  const m = subject.match(PREFIX_RE);
  if (!m) return { key: 'other', text: subject };
  let key = m[1].toLowerCase();
  if (GROUP_ALIASES[key]) key = GROUP_ALIASES[key];
  if (!GROUPS.some((g) => g.key === key)) key = 'other';
  return { key, text: m[2] || subject };
}

function shortHash(h) { return (h || '').slice(0, 7); }
function escMd(s) { return (s || '').replace(/\|/g, '\\|').replace(/\n/g, ' '); }

/* ──────────────────────────── main ────────────────────────────────────── */

(function main() {
  const today = new Date().toISOString().slice(0, 10);
  const reportPath = `/tmp/release-notes-${today}.md`;

  const perRepo = []; // { repo, commits, groups: {key: [commit]} }
  let totalCommits = 0;

  for (const repo of REPOS) {
    if (!isGitRepo(repo.dir)) {
      perRepo.push({ repo, missing: true, commits: [], groups: {} });
      continue;
    }
    const all = gitLog(repo.dir);
    const filtered = all.filter((c) => !isAutoGenerated(c));
    const groups = {};
    for (const c of filtered) {
      const cls = classify(c.subject);
      if (!groups[cls.key]) groups[cls.key] = [];
      groups[cls.key].push({ ...c, text: cls.text });
    }
    perRepo.push({ repo, missing: false, commits: filtered, groups });
    totalCommits += filtered.length;
  }

  /* ────────────────────────── compose ───────────────────────────────── */

  let md = '';
  md += `# Release Notes — ${today}\n`;
  md += `_Period: last 7 days. Excludes merges, dependabot/renovate/CI noise, and tiny SW/cache version bumps._\n\n`;
  md += `**Total commits:** ${totalCommits} across ${perRepo.filter((r) => !r.missing).length} repos.\n\n`;

  /* English section ------------------------------------------------------ */
  md += `---\n\n## English\n\n`;
  for (const r of perRepo) {
    md += `### ${r.repo.name}\n\n`;
    if (r.missing) { md += `_Repo not found at \`${r.repo.dir}\`._\n\n`; continue; }
    if (r.commits.length === 0) { md += `_No notable commits in the last 7 days._\n\n`; continue; }
    // print groups in order, skipping empty
    const seen = new Set();
    for (const g of GROUPS) {
      if (seen.has(g.en)) continue;
      // collect across all keys that resolve to this english header
      const merged = [];
      for (const gg of GROUPS) {
        if (gg.en !== g.en) continue;
        for (const c of (r.groups[gg.key] || [])) merged.push(c);
      }
      if (merged.length === 0) continue;
      seen.add(g.en);
      md += `**${g.en}** (${merged.length})\n\n`;
      for (const c of merged) {
        md += `- \`${shortHash(c.hash)}\` ${escMd(c.text)}\n`;
      }
      md += `\n`;
    }
  }

  /* Hebrew section ------------------------------------------------------- */
  md += `---\n\n## עברית\n\n`;
  for (const r of perRepo) {
    md += `### ${r.repo.he}\n\n`;
    if (r.missing) { md += `_מאגר לא נמצא: \`${r.repo.dir}\`._\n\n`; continue; }
    if (r.commits.length === 0) { md += `_אין קומיטים בולטים בשבוע האחרון._\n\n`; continue; }
    const seen = new Set();
    for (const g of GROUPS) {
      if (seen.has(g.he)) continue;
      const merged = [];
      for (const gg of GROUPS) {
        if (gg.he !== g.he) continue;
        for (const c of (r.groups[gg.key] || [])) merged.push(c);
      }
      if (merged.length === 0) continue;
      seen.add(g.he);
      md += `**${g.he}** (${merged.length})\n\n`;
      for (const c of merged) {
        md += `- \`${shortHash(c.hash)}\` ${escMd(c.text)}\n`;
      }
      md += `\n`;
    }
  }

  md += `---\n_Generated ${new Date().toISOString()}_\n`;
  fs.writeFileSync(reportPath, md, 'utf8');

  console.log(`Repos scanned : ${REPOS.length}`);
  console.log(`Total commits : ${totalCommits}`);
  console.log(`Report        : ${reportPath}`);
  process.exit(0);
})();
